//! Verifier core for Merkle Tree Certificates (draft-ietf-plants-merkle-tree-certs)
//! landmarks and inclusion proofs, prototyping the device-side checks that
//! draft-kwiatkowski-mtc-iot layers onto EDHOC/LAKE.
//!
//! This is deliberately independent of any other MTC implementation: every
//! algorithm here (leaf/node hashing, inclusion and consistency proof
//! evaluation, cosignature verification) is written from the spec, and is
//! checked against test vectors generated by a separate Go program under
//! `vectors/` so two independent implementations have to agree.

pub mod cosign;
pub mod hash;
pub mod proof;
pub mod subtree;
pub mod trustanchorid;

pub use hash::{hash_empty, hash_leaf, hash_node, HashValue, HASH_SIZE};
